  let nextMileagePay    = ('mileage_pay_rate'    in body) ? body.mileage_pay_rate    : current.mileage_pay_rate;
  let nextMileageCharge = ('mileage_charge_rate' in body) ? body.mileage_charge_rate : current.mileage_charge_rate;

  if ('mileage_pay_rate' in body) {
    if (body.mileage_pay_rate === '' || body.mileage_pay_rate === null || body.mileage_pay_rate === undefined) {
      nextMileagePay = null;
    } else {
      const n = Number(body.mileage_pay_rate);
      if (!Number.isFinite(n) || n < 0) {
        return withCORS(env, req, badRequest('mileage_pay_rate must be a non-negative number if provided'));
      }
      nextMileagePay = n;
    }
  }

  if ('mileage_charge_rate' in body) {
    if (body.mileage_charge_rate === '' || body.mileage_charge_rate === null || body.mileage_charge_rate === undefined) {
      nextMileageCharge = null;
    } else {
      const n = Number(body.mileage_charge_rate);
      if (!Number.isFinite(n) || n < 0) {
        return withCORS(env, req, badRequest('mileage_charge_rate must be a non-negative number if provided'));
      }
      nextMileageCharge = n;
    }
  }

  // Validate default_submission_mode early if present
  let desiredDefaultSubmissionMode = current.default_submission_mode ?? null;
  if ('default_submission_mode' in body) {
    const parsed = parseDefaultSubmissionMode(body.default_submission_mode);
    if (parsed === '__INVALID__') {
      return withCORS(env, req, badRequest('default_submission_mode must be ELECTRONIC or MANUAL (or INHERIT/null to clear)'));
    }
    desiredDefaultSubmissionMode = parsed;
  }

  // Core authority becomes immutable only after real lifecycle progression.
  // Planned weeks and unprocessed Timesheets remain editable.
  if (hasProgressedTimesheets) {
    const changedCore = [];
    const normString = (value) => value == null ? '' : String(value).trim();
    const normUpper = (value) => normString(value).toUpperCase();
    const normTri = (value) => value == null ? null : clampBool(value, false);
    const compareString = (key, { upper = false } = {}) => {
      if (!Object.prototype.hasOwnProperty.call(body, key)) return;
      const normalize = upper ? normUpper : normString;
      if (normalize(body[key]) !== normalize(current[key])) changedCore.push(key);
    };
    const compareTri = (key) => {
      if (!Object.prototype.hasOwnProperty.call(body, key)) return;
      if (normTri(body[key]) !== normTri(current[key])) changedCore.push(key);
    };

    compareString('candidate_id');
    compareString('client_id');
    compareString('role');
    compareString('band');
    compareString('pay_method_snapshot', { upper: true });
    compareString('weekly_timesheet_source', { upper: true });
    [
      'overrideclientsettings',
      'is_nhsp',
      'autoprocess_hr',
      'requires_hr',
      'no_timesheet_required',
      'self_bill',
      'daily_calc_of_invoices',
      'group_nightsat_sunbh',
      'auto_invoice'
    ].forEach(compareTri);

    if (Object.prototype.hasOwnProperty.call(body, 'default_submission_mode')) {
      const nextMode = overrideclientsettings ? (desiredDefaultSubmissionMode ?? null) : (current.default_submission_mode ?? null);
      if ((nextMode ?? null) !== (current.default_submission_mode ?? null)) changedCore.push('default_submission_mode');
    }

    if (changedCore.length) {
      return withCORS(env, req, badRequest(
        `Core contract details cannot be changed after a Timesheet has been processed, authorised, invoiced or paid. Blocked fields: ${[...new Set(changedCore)].join(', ')}`
      ));
    }
  }

  // ---- detect attempted week-ending change (used for safe blocking under submitted TS) ----
  const curWewNum = Number(current.week_ending_weekday_snapshot ?? 0);
  const bodyWewNum = ('week_ending_weekday_snapshot' in body) ? Number(body.week_ending_weekday_snapshot) : curWewNum;
  const attemptedWeekdayChange = ('week_ending_weekday_snapshot' in body) && (Number.isFinite(bodyWewNum)) && (bodyWewNum !== curWewNum);

  if (hasWeeks && attemptedWeekdayChange) {
    return withCORS(env, req, badRequest('Week-ending day cannot be changed after contract weeks have been created.'));
  }

  if (hasProgressedTimesheets) {
    // Treat omitted fields as “no change” (defensive)
    const effCandidateId = ('candidate_id' in body) ? body.candidate_id : current.candidate_id;
    const effClientId    = ('client_id'    in body) ? body.client_id    : current.client_id;

    if (effCandidateId !== current.candidate_id) return withCORS(env, req, badRequest('Cannot change candidate after timesheets have been submitted'));
    if (effClientId    !== current.client_id)    return withCORS(env, req, badRequest('Cannot change client after timesheets have been submitted'));

    const pmBody = String(body.pay_method_snapshot || current.pay_method_snapshot || '').toUpperCase();
    const pmCur  = String(current.pay_method_snapshot || '').toUpperCase();

    if (pmBody !== pmCur) {
      return withCORS(env, req, badRequest('Cannot change pay_method_snapshot after timesheets have been submitted'));
    }

    const curNorm = normaliseRatesForCompare(current.rates_json || {}, pmCur);
    const inNorm  = normaliseRatesForCompare(body.rates_json || {}, pmCur);

    if (JSON.stringify(inNorm) !== JSON.stringify(curNorm)) {
      return withCORS(env, req, badRequest('Cannot change rates after timesheets have been submitted'));
    }

    if (nextMileagePay !== current.mileage_pay_rate || nextMileageCharge !== current.mileage_charge_rate) {
      return withCORS(env, req, badRequest('Cannot change mileage rates after timesheets have been submitted'));
    }

    if ('additional_rates_json' in body) {
      const curA = normaliseAdditionalRates(current.additional_rates_json);
      const inA  = normaliseAdditionalRates(body.additional_rates_json);
      if (JSON.stringify(inA || null) !== JSON.stringify(curA || null)) {
        return withCORS(env, req, badRequest('Cannot change additional rates after timesheets have been submitted'));
      }
    }

    // Block changing overrideclientsettings once real TS exist
    if (hasOverrideClientSettings && overrideclientsettings !== !!current.overrideclientsettings) {
      return withCORS(env, req, badRequest('Cannot change overrideclientsettings after timesheets have been submitted'));
    }

    // Block changing week-ending day once real TS exist (explicit and safe)
    if (attemptedWeekdayChange) {
      return withCORS(env, req, badRequest('Cannot change week_ending_weekday_snapshot after timesheets have been submitted'));
    }

    // Only block default_submission_mode when overrideclientsettings=true AND it would actually change stored value.
    if ('default_submission_mode' in body && overrideclientsettings === true) {
      const curDsm = current.default_submission_mode ?? null;
      const nextDsm = desiredDefaultSubmissionMode ?? null;
      if (nextDsm !== curDsm) {
        return withCORS(env, req, badRequest('Cannot change default_submission_mode after timesheets have been submitted'));
      }
    }
  }

  // Storage rules for default_submission_mode
  let default_submission_mode_to_store = null;
  if (overrideclientsettings === true) {
    default_submission_mode_to_store = desiredDefaultSubmissionMode ?? null;
  } else {
    default_submission_mode_to_store = hasProgressedTimesheets ? (current.default_submission_mode ?? null) : null;
  }

  const extraWarnings = [];
  let wew;

  if (hasAnyTimesheets) {
    wew = Number(current.week_ending_weekday_snapshot ?? 0);
  } else {
    if ('week_ending_weekday_snapshot' in body) {
      const cand = Number(body.week_ending_weekday_snapshot);
      if (Number.isInteger(cand) && cand >= 0 && cand <= 6) {
        wew = cand;
      } else {
        try {
          const targetClientId = body.client_id || current.client_id;
          const authority = await loadPolicy(
            env,
            targetClientId,
            toYmd(body.start_date) || current.start_date,
            { workflow: 'WEEKLY' }
          );
          const derived = Number(authority?.week_ending_weekday);
          wew = (Number.isInteger(derived) && derived >= 0 && derived <= 6) ? derived : 0;
        } catch (error) {
          return withCORS(env, req, badRequest(error?.message || 'CONTRACT_SETTINGS_AUTHORITY_UNAVAILABLE'));
        }
      }
    } else if (body.client_id && body.client_id !== current.client_id) {
      try {
        const authority = await loadPolicy(
          env,
          body.client_id,
          toYmd(body.start_date) || current.start_date,
          { workflow: 'WEEKLY' }
        );
        const derived = Number(authority?.week_ending_weekday);
        wew = (Number.isInteger(derived) && derived >= 0 && derived <= 6) ? derived : 0;
      } catch (error) {
        return withCORS(env, req, badRequest(error?.message || 'CONTRACT_SETTINGS_AUTHORITY_UNAVAILABLE'));
      }
    } else {
      wew = Number(current.week_ending_weekday_snapshot ?? 0);
    }
  }

  const newStart = ('start_date' in body) ? toYmd(body.start_date) : current.start_date;
  const newEnd   = ('end_date'   in body) ? toYmd(body.end_date)   : current.end_date;

  let protectedWorkBoundary;
  try {
    protectedWorkBoundary = await contractWorkedDateBoundary(env, contractId);
    const refusal = contractWorkedDateRefusal(protectedWorkBoundary, newStart, newEnd);
    if (refusal) return withCORS(env, req, badRequest(refusal));
  } catch (error) {
    return withCORS(env, req, serverError(error.message));
  }

  const hasIsAdHoc = Object.prototype.hasOwnProperty.call(body, 'is_ad_hoc');
  const isAdHoc = hasIsAdHoc ? clampBool(body.is_ad_hoc, !!current.is_ad_hoc) : !!current.is_ad_hoc;
  let queryEmailOverride;
  try {
    queryEmailOverride = normalizeContractQueryEmailOverride(body, current);
  } catch (error) {
    return withCORS(env, req, badRequest(error?.message || 'Invalid timesheet-query email override'));
  }
  let replacementBreakEntryMode;
  try {
    replacementBreakEntryMode = Object.prototype.hasOwnProperty.call(body, 'timesheet_break_entry_mode')
      ? normalizeTimesheetBreakEntryMode(body.timesheet_break_entry_mode, { nullable: true })
      : (current.timesheet_break_entry_mode ?? null);
  } catch (error) {
    return withCORS(env, req, badRequest(error?.message || 'Invalid break-entry mode'));
  }
  let replacementCandidateExpenseEmail;
  try {
    replacementCandidateExpenseEmail = Object.prototype.hasOwnProperty.call(body, 'candidate_expense_invoice_email_override')
      ? normalizeCandidateExpenseInvoiceEmail(body.candidate_expense_invoice_email_override)
      : (current.candidate_expense_invoice_email_override ?? null);
  } catch (error) {
    return withCORS(env, req, badRequest(error?.message || 'Invalid Candidate expense invoice email'));
  }

  const patch = {
    candidate_id: ('candidate_id' in body ? body.candidate_id : current.candidate_id),
    client_id:    body.client_id,
    role:         body.role ?? current.role,
    band:         body.band ?? current.band,
    display_site: (body.display_site ?? current.display_site ?? '').toString().trim(),
    ward_hint:    (body.ward_hint ?? current.ward_hint ?? '').toString().trim(),
    start_date:   newStart,
    end_date:     newEnd,

    is_ad_hoc: isAdHoc,

    overrideclientsettings,
    is_nhsp:               ('is_nhsp' in body)               ? boolOrNull(body.is_nhsp, !!current.is_nhsp) : (current.is_nhsp ?? null),
    autoprocess_hr:        ('autoprocess_hr' in body)        ? boolOrNull(body.autoprocess_hr, !!current.autoprocess_hr) : (current.autoprocess_hr ?? null),
    requires_hr:           ('requires_hr' in body)           ? boolOrNull(body.requires_hr, !!current.requires_hr) : (current.requires_hr ?? null),
    no_timesheet_required: ('no_timesheet_required' in body) ? boolOrNull(body.no_timesheet_required, !!current.no_timesheet_required) : (current.no_timesheet_required ?? null),
    daily_calc_of_invoices:('daily_calc_of_invoices' in body)? boolOrNull(body.daily_calc_of_invoices, !!current.daily_calc_of_invoices) : (current.daily_calc_of_invoices ?? null),
    group_nightsat_sunbh:  ('group_nightsat_sunbh' in body)  ? boolOrNull(body.group_nightsat_sunbh, !!current.group_nightsat_sunbh) : (current.group_nightsat_sunbh ?? null),
    self_bill:             ('self_bill' in body)             ? boolOrNull(body.self_bill, !!current.self_bill) : (current.self_bill ?? null),

    weekly_timesheet_source: current.weekly_timesheet_source ?? null,

    hr_attach_to_invoice:  ('hr_attach_to_invoice' in body)  ? boolOrNull(body.hr_attach_to_invoice, !!current.hr_attach_to_invoice) : (current.hr_attach_to_invoice ?? null),
    ts_attach_to_invoice:  ('ts_attach_to_invoice' in body)  ? boolOrNull(body.ts_attach_to_invoice, !!current.ts_attach_to_invoice) : (current.ts_attach_to_invoice ?? null),
    timesheet_break_entry_mode: replacementBreakEntryMode,
    candidate_expenses_require_separate_timesheet_override:
      Object.prototype.hasOwnProperty.call(body, 'candidate_expenses_require_separate_timesheet_override')
        ? boolOrNull(body.candidate_expenses_require_separate_timesheet_override, false)
        : (current.candidate_expenses_require_separate_timesheet_override ?? null),
    candidate_expense_invoice_email_override: replacementCandidateExpenseEmail,

    pay_method_snapshot: String(body.pay_method_snapshot||current.pay_method_snapshot).toUpperCase(),

    default_submission_mode: default_submission_mode_to_store,

    week_ending_weekday_snapshot: wew,
    rates_json: body.rates_json || current.rates_json || {},
    std_schedule_json,
    std_hours_json,
    bucket_labels_json: ('bucket_labels_json' in body) ? (body.bucket_labels_json || null) : (current.bucket_labels_json || null),

    auto_invoice: ('auto_invoice' in body) ? clampBool(body.auto_invoice, current.auto_invoice) : current.auto_invoice,
    require_reference_to_pay: ('require_reference_to_pay' in body) ? clampBool(body.require_reference_to_pay, current.require_reference_to_pay) : current.require_reference_to_pay,
    require_reference_to_invoice: ('require_reference_to_invoice' in body) ? clampBool(body.require_reference_to_invoice, current.require_reference_to_invoice) : current.require_reference_to_invoice,

    mileage_pay_rate: nextMileagePay,
    mileage_charge_rate: nextMileageCharge,
    send_ts_queries_to_different_email: queryEmailOverride.send_ts_queries_to_different_email,
    ts_queries_alt_email_address: queryEmailOverride.ts_queries_alt_email_address,
    updated_at: nowIso(),
    additional_rates_json: ('additional_rates_json' in body)
      ? normaliseAdditionalRates(body.additional_rates_json)
      : (current.additional_rates_json || null)
  };

  if (patch.is_nhsp === true && patch.autoprocess_hr === true) {
    return withCORS(env, req, badRequest('Invalid contract route: is_nhsp=true and autoprocess_hr=true cannot both be true.'));
  }
  if (patch.no_timesheet_required === true && patch.autoprocess_hr !== true) {
    return withCORS(env, req, badRequest('Invalid contract route: no_timesheet_required=true requires autoprocess_hr=true.'));
  }

  if (patch.is_nhsp === true) {
    if (patch.hr_attach_to_invoice === true || patch.ts_attach_to_invoice === true) {
      return withCORS(env, req, badRequest('NHSP route: attachments must be disabled (hr_attach_to_invoice/ts_attach_to_invoice cannot be true).'));
    }
  }
  if (patch.no_timesheet_required === true) {
    if (patch.ts_attach_to_invoice === true) {
      return withCORS(env, req, badRequest('No-timesheets route: ts_attach_to_invoice cannot be true.'));
    }
  }

  if (!hasProgressedTimesheets) {
    const requestedWeeklySource = String(body.weekly_timesheet_source || '').trim().toUpperCase();
    if (requestedWeeklySource && !['NONE','NHSP','HEALTHROSTER'].includes(requestedWeeklySource)) {
      return withCORS(env, req, badRequest('weekly_timesheet_source must be NONE, NHSP or HEALTHROSTER'));
    }
    patch.weekly_timesheet_source = requestedWeeklySource || (
      patch.is_nhsp === true ? 'NHSP' : (patch.autoprocess_hr === true ? 'HEALTHROSTER' : 'NONE')
    );
  }

  if (hasProgressedTimesheets) {
    const changed = [];
    const curTri = (v) => (v === undefined ? null : v);

    const triKeys = [
      'is_nhsp',
      'autoprocess_hr',
      'requires_hr',
      'no_timesheet_required',
      'self_bill',
      'daily_calc_of_invoices',
      'group_nightsat_sunbh',
      'hr_attach_to_invoice',
      'ts_attach_to_invoice'
    ];

    for (const k of triKeys) {
      const desired = patch[k];
      const cur = curTri(current[k]);
      if (desired !== cur) changed.push(k);
    }

    const boolKeys = [
      'auto_invoice',
      'require_reference_to_pay',
      'require_reference_to_invoice'
    ];

    for (const k of boolKeys) {
      const desired = !!patch[k];
      const cur = !!current[k];
      if (desired !== cur) changed.push(k);
    }

    if (overrideclientsettings !== !!current.overrideclientsettings) changed.push('overrideclientsettings');
    if ((current.default_submission_mode ?? null) !== (patch.default_submission_mode ?? null)) changed.push('default_submission_mode');

    if (changed.length) {
      return withCORS(env, req, badRequest(
        `Cannot change contract settings because a Timesheet has been processed, authorised, invoiced or paid. Blocked fields: ${changed.join(', ')}`
      ));
    }
  }

  const pmSnapReplace = String(patch.pay_method_snapshot || '').toUpperCase();
  if (patch.rates_json && pmSnapReplace) {
    const keepPrefixesReplace =
      pmSnapReplace === 'PAYE'     ? ['paye_','charge_'] :
      pmSnapReplace === 'UMBRELLA' ? ['umb_','charge_'] :
                                     ['charge_'];
    const cleaned = {};
    for (const [k, v] of Object.entries(patch.rates_json)) {
      if (keepPrefixesReplace.some(pre => k.startsWith(pre))) {
        cleaned[k] = v;
      }
    }
    patch.rates_json = cleaned;
  }

  if (hasProgressedTimesheets) {
    patch.candidate_id = current.candidate_id;
    patch.client_id    = current.client_id;
    patch.pay_method_snapshot = String(current.pay_method_snapshot || patch.pay_method_snapshot || '').toUpperCase();
    patch.rates_json = (current.rates_json && typeof current.rates_json === 'object') ? current.rates_json : (current.rates_json || {});
    patch.additional_rates_json = current.additional_rates_json || null;
  }

  try { console.log('[CONTRACTS][REPLACE] patch', { contractId, patch }); } catch {}

  const res = await fetch(`${env.SUPABASE_URL}/rest/v1/contracts?id=eq.${enc(contractId)}`, {
    method: 'PATCH',
    headers: { ...sbHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify(patch)
  });
  if (!res.ok) return withCORS(env, req, serverError(await res.text()));
  let updated = (await res.json().catch(()=>[]))[0];

  const windowChanged = (String(newStart || '') !== String(current.start_date || '')) ||
                        (String(newEnd   || '') !== String(current.end_date   || ''));

  const weekdayChanged = Number(wew) !== Number(current.week_ending_weekday_snapshot ?? 0);

  if (windowChanged) {
    const del = await fetch(
      `${env.SUPABASE_URL}/rest/v1/contract_weeks?contract_id=eq.${enc(contractId)}&timesheet_id=is.null&or=(week_ending_date.lt.${enc(newStart)},week_ending_date.gt.${enc(newEnd)})`,
      { method:'DELETE', headers: { ...sbHeaders(env), 'Prefer':'return-minimal' } }
    );
    try { await del.arrayBuffer(); } catch {}
  }

  if (!body.skip_generate_weeks) {
    if (weekdayChanged) {
      if (!hasAnyTimesheets) {
        const delAllDraft = await fetch(
          `${env.SUPABASE_URL}/rest/v1/contract_weeks?contract_id=eq.${enc(contractId)}&timesheet_id=is.null`,
          { method:'DELETE', headers: { ...sbHeaders(env), 'Prefer':'return-minimal' } }
        );
        try { await delAllDraft.arrayBuffer(); } catch {}

        try {
          await handleContractsGenerateWeeks(env, req, contractId);
        } catch (e) {
          try { console.warn('[CONTRACTS][REPLACE] regenerate weeks (weekdayChanged) failed', { contractId, error: e?.message || String(e) }); } catch {}
        }
      }
    } else if (windowChanged) {
      try {
        await handleContractsGenerateWeeks(env, req, contractId);
      } catch (e) {
        try { console.warn('[CONTRACTS][REPLACE] generate weeks (windowChanged) failed', { contractId, error: e?.message || String(e) }); } catch {}
      }
    }
  }

  const { min_ts_date, max_ts_date } = protectedWorkBoundary;

  let min_plan_date = null, max_plan_date = null;
  try {
    const { rows: wkRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
      `?contract_id=eq.${enc(contractId)}&select=planned_schedule_json`
    );
    for (const w of (wkRows||[])) {
      const raw = w?.planned_schedule_json;
      const arr = Array.isArray(raw) ? raw : (typeof raw === 'string' ? JSON.parse(raw) : []);
      for (const d of arr.map(x=>x?.date).filter(Boolean)) {
        if (!min_plan_date || d < min_plan_date) min_plan_date = d;
        if (!max_plan_date || d > max_plan_date) max_plan_date = d;
      }
    }
  } catch {}

  let normStart = updated?.start_date || newStart;
  let normEnd   = updated?.end_date   || newEnd;

  if (min_ts_date)  normStart = (!normStart || min_ts_date < normStart) ? min_ts_date : normStart;
  if (max_ts_date)  normEnd   = (!normEnd   || max_ts_date > normEnd)   ? max_ts_date : normEnd;
  if (min_plan_date) normStart = (!normStart || min_plan_date < normStart) ? min_plan_date : normStart;
  if (max_plan_date) normEnd   = (!normEnd   || max_plan_date > normEnd)   ? max_plan_date : normEnd;

  if (normStart) normEnd = normEnd || normStart;

  if ((normStart && normStart !== updated.start_date) || (normEnd && normEnd !== updated.end_date)) {
    const normRes = await fetch(`${env.SUPABASE_URL}/rest/v1/contracts?id=eq.${enc(contractId)}`, {
      method: 'PATCH',
      headers: { ...sbHeaders(env), 'Prefer': 'return=representation' },
      body: JSON.stringify({ start_date: normStart, end_date: normEnd, updated_at: nowIso() })
    });
    if (normRes.ok) updated = (await normRes.json().catch(()=>[]))[0] || updated;
  }

  // ✅ WARN-ONLY: schedule clash warnings via detectScheduleClashesInternal (never block)
  let scheduleClashes = null;
  try {
    const candId = updated?.candidate_id || null;

    if (candId && typeof detectScheduleClashesInternal === 'function') {
      const proposed_entries = [];
      const seen = new Set();

      if (patch.is_ad_hoc === true) {
        scheduleClashes = { clash_count: 0, clashes: [], note: 'Ad-hoc contract: no template-based proposed entries to check.' };
      } else if (patch.std_schedule_json && typeof patch.std_schedule_json === 'object') {
        const names = ['sun','mon','tue','wed','thu','fri','sat'];

        const d0 = new Date(String(updated.start_date) + 'T00:00:00Z');
        const d1 = new Date(String(updated.end_date)   + 'T00:00:00Z');

        if (!Number.isNaN(d0.getTime()) && !Number.isNaN(d1.getTime()) && d0 <= d1) {
          for (let dt = new Date(d0); dt <= d1; dt.setUTCDate(dt.getUTCDate() + 1)) {
            const ymd = toYmd(dt);
            if (!ymd) continue;

            const wkKey = names[dt.getUTCDay()];
            const tpl = patch.std_schedule_json?.[wkKey];
            if (!tpl || typeof tpl !== 'object') continue;

            const start = (tpl.start == null ? '' : String(tpl.start)).trim();
            const end   = (tpl.end   == null ? '' : String(tpl.end)).trim();
            if (!start || !end) continue;

            const bm = (tpl.break_minutes != null) ? Number(tpl.break_minutes) : 0;
            const key = `${ymd}|${start}|${end}|${Number.isFinite(bm) ? bm : 0}`;
            if (seen.has(key)) continue;
            seen.add(key);

            proposed_entries.push({
              date: ymd,
              start,
              end,
              breaks: Array.isArray(tpl.breaks) ? tpl.breaks : [],
              break_minutes: Number.isFinite(bm) ? bm : 0,
              overnight: tpl.overnight === true
            });
          }
        }

        if (proposed_entries.length) {
          scheduleClashes = await detectScheduleClashesInternal(env, {
            candidate_id: candId,
            proposed_entries,
            ignore_contract_ids: [updated.id]
          });
        } else {
          scheduleClashes = { clash_count: 0, clashes: [], note: 'No timed template entries available to check.' };
        }
      } else {
        scheduleClashes = { clash_count: 0, clashes: [], note: 'No std_schedule_json available to check.' };
      }
    }
  } catch (e) {
    scheduleClashes = { clash_count: 0, clashes: [], error: String(e?.message || e) };
  }

  const warnings0 = await computePayMethodWarnings(env, { ...current, ...updated });
  const warnings = Array.isArray(warnings0) ? [...warnings0, ...extraWarnings] : [...extraWarnings];
  return withCORS(env, req, ok({ contract: updated, warnings, warnings_extra: { schedule_clashes: scheduleClashes } }));
}

