  } catch (e) {
    try {
      console.error('[PLAN_RANGES][EXCEPTION]', {
        contractId: String(contractId || ''),
        err_name: e?.name || null,
        err_message: e?.message || String(e || ''),
        err_stack: e?.stack || null
      });
    } catch {}
